{
  "name": "opencode-hauke-cloud",
  "version": "1.0.1",
  "description": "hauke.cloud for opencode: OIDC sign-in, model discovery and mem0 long-term memory",
  "type": "module",
  "license": "MIT",
  "author": "Hauke Mettendorf",
  "repository": {
    "type": "git",
    "url": "https://github.com/hauke-cloud/opencode-hauke-cloud"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "oauth2",
    "oidc",
    "pkce",
    "mem0"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "files": [
    "dist",
    "!dist/__tests__",
    "README.md"
  ],
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "dev": "tsc -p tsconfig.json --watch",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "pretest": "npm run build",
    "test": "node --test \"dist/**/*.test.js\""
  },
  "devDependencies": {
    "@opencode/plugin": "^2.0.11",
    "@types/node": "^26.6.1",
    "typescript": "7.0.2"
  }
}
